:root {
  --bg: #1e1e2f;
  --surface: #2a2a40;
  --card-back: #3a3a5a;
  --text: #f0f0f5;
  --accent: #6c63ff;
  --accent-hover: #5a52d5;
  --matched: #4caf50;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
}

.game {
  background: var(--surface);
  border-radius: 20px;
  padding: 24px;
  max-width: 520px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 1.8rem;
  margin-bottom: 16px;
  letter-spacing: 0.5px;
}

.status {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
  font-size: 1.1rem;
  min-height: 2rem;
}

.win-message {
  color: var(--matched);
  font-weight: 700;
  font-size: 1.2rem;
}

.board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-bottom: 24px;
}

.card {
  aspect-ratio: 1 / 1;
  background: var(--card-back);
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: transform 0.2s, background 0.3s, box-shadow 0.2s;
  position: relative;
  overflow: hidden;
  font-size: 1.5rem;
  color: transparent;
  display: flex;
  justify-content: center;
  align-items: center;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);
  padding: 0;
}

.card::before {
  content: '?';
  color: var(--text);
  font-weight: 700;
  font-size: 1.5rem;
  position: absolute;
}

.card.flipped::before,
.card.matched::before {
  content: '';
}

.card.flipped,
.card.matched {
  background: var(--accent);
  color: var(--text);
}

.card.matched {
  background: var(--matched);
  cursor: default;
  pointer-events: none;
}

.card:hover:not(.flipped):not(.matched) {
  background: var(--accent-hover);
  transform: scale(1.05);
}

.card:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.card:active:not(.matched) {
  transform: scale(0.95);
}

.new-game {
  background: var(--accent);
  color: var(--text);
  border: none;
  border-radius: 12px;
  padding: 14px 32px;
  font-size: 1.1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.new-game:hover {
  background: var(--accent-hover);
}

.new-game:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 3px;
}

.new-game:active {
  transform: scale(0.97);
}

@media (max-width: 400px) {
  .game {
    padding: 16px;
  }
  .board {
    gap: 8px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .card {
    border-radius: 8px;
  }
  .card::before {
    font-size: 1.2rem;
  }
}

const COLORS = [
  '#e63946', '#f4a261', '#2a9d8f', '#457b9d',
  '#9b5de5', '#f15bb5', '#00bbf9', '#fee440'
];

const boardEl = document.getElementById('board');
const movesEl = document.getElementById('moves');
const winEl = document.getElementById('win-message');
const newGameBtn = document.getElementById('new-game');

let cards = [];
let flipped = [];
let matched = 0;
let moves = 0;
let lock = false;

function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function createCard(color, index) {
  const btn = document.createElement('button');
  btn.className = 'card';
  btn.type = 'button';
  btn.setAttribute('aria-label', 'Hidden card');
  btn.dataset.color = color;
  btn.dataset.index = index;
  btn.style.setProperty('--card-color', color);
  btn.addEventListener('click', () => flipCard(btn));
  return btn;
}

function flipCard(card) {
  if (lock || card.classList.contains('flipped') || card.classList.contains('matched')) return;
  card.classList.add('flipped');
  card.setAttribute('aria-label', 'Flipped card');
  card.style.background = card.dataset.color;
  flipped.push(card);

  if (flipped.length === 2) {
    moves++;
    movesEl.textContent = `Moves: ${moves}`;
    lock = true;
    const [a, b] = flipped;
    if (a.dataset.color === b.dataset.color) {
      a.classList.add('matched');
      b.classList.add('matched');
      a.setAttribute('aria-label', 'Matched card');
      b.setAttribute('aria-label', 'Matched card');
      matched++;
      flipped = [];
      lock = false;
      if (matched === 8) {
        winEl.hidden = false;
      }
    } else {
      setTimeout(() => {
        a.classList.remove('flipped');
        b.classList.remove('flipped');
        a.style.background = '';
        b.style.background = '';
        a.setAttribute('aria-label', 'Hidden card');
        b.setAttribute('aria-label', 'Hidden card');
        flipped = [];
        lock = false;
      }, 800);
    }
  }
}

function initGame() {
  boardEl.innerHTML = '';
  flipped = [];
  matched = 0;
  moves = 0;
  lock = false;
  movesEl.textContent = 'Moves: 0';
  winEl.hidden = true;

  const deck = shuffle([...COLORS, ...COLORS]);
  deck.forEach((color, i) => {
    boardEl.appendChild(createCard(color, i));
  });
}

newGameBtn.addEventListener('click', initGame);
initGame();
